FamilyTree.person({"id":"christoffel","name":"Christoffel Bundervoet","dates":"1709 Evergem – 19 Nov 1786 Evergem","confidence":"sup","surname":"Bundervoet","family":"bundervoet","born":"1709 Evergem","order":"1709","died":"19 Nov 1786 Evergem","branch":"Bundervoet","line":"bundervoet","father":"joannes_b","mother":"livina_stockman","spouses":[{"id":"bogaert","name":"Petronilla Bogaert"}],"source":"paulderidder; glorieuxp","note":"Born 1709, Evergem. Son of Joannes Bundervoet's FIRST marriage, to Livina Stockman (not his second wife De Wilde). Children with Petronilla Bogaert: Guillaume (1731), Joanna Maria (1741), Maria Anna (1746), Philippus Jacobus (1756)."});
