FamilyTree.person({"id":"daniel_bocklandt","name":"Daniel Bocklandt","dates":"1768 – 1837","confidence":"sup","surname":"Bocklandt","family":"bocklandt","born":"1768","order":"1768","died":"1837","branch":"DeKeyser","line":"de-keyser","spouses":[{"id":"philippa_vanpuyenbroeck","name":"Philippa Van Puyenbroeck","detail":"m. 1801"}],"source":"wete1998 (Erik Bekaert) — Hamme (O-Vl) specialist","note":"FRONTIER (top of the Bocklandt line in the wete1998 tree) — paternal great-grandfather of Louise Bocklandt. Married Philippa Van Puyenbroeck in 1801. Of Hamme (Oost-Vlaanderen). His own parents are not recorded in the tree; the Hamme O-Vl parish/civil registers (Rijksarchief AGATHA) are the place to push further."});
