FamilyTree.person({"id":"etienne_thumas","name":"Etienne Thumas","dates":"d. 18 Oct 1812 Grez-Doiceau","confidence":"sup","surname":"Thumas","family":"thumas","sex":"m","died":"18 Oct 1812 Grez-Doiceau","branch":"Thumas","line":"thumas","father":"georgeslambert_t","mother":"quinart","source":"Death act of Etienne Thumas, Grez-Doiceau, 18 October 1812","note":"Son of [[georgeslambert_t]] and [[quinart]], and so a brother of [[georges2_t]].\n\nHe is known from his own Grez-Doiceau death act of 18 October 1812, which names both his\nparents ([[S13]]). That act is the reason his mother's marriage is corroborated at all.\n\nNo birth date: the act is indexed under the death and has not been read as an image, so his\nage — which the act almost certainly states, as the other Grez-Doiceau acts of this period do\n— is unread. Reading it would date his birth and show whether he died a child or a grown man."});
FamilyTree.person({"id":"eugenia_dutreeuw","name":"Eugenia Henrica Dutreeuw","dates":"b. 28 Feb 1808 Diksmuide","confidence":"sup","surname":"Dutreeuw","family":"dutreeuw","born":"28 Feb 1808 Diksmuide","order":"1808-02-28","branch":"Bundervoet","line":"van-iseghem","father":"ludovicus_dutreeuw","mother":"ludovica_ellebout","spouses":[{"id":"carolus_vanald","name":"Carolus Ludovicus Vanalderweireldt","detail":"m. Diksmuide, 4 Jun 1828"}],"source":"bartvanhooren (Bart Vanhooren)","note":"Daughter of Ludovicus Dutreeuw & Ludovica Ellebout; mother of Ludovica Vanalderweireldt (1845)."});
FamilyTree.person({"id":"eugenius_dv","name":"Eugenius Alphonsius Devriendt","dates":"b. 13 Apr 1882 Stene","confidence":"doc","surname":"Devriendt","family":"devriendt","born":"13 Apr 1882 Stene","order":"1882-04-13","branch":"Bundervoet","line":"van-iseghem","father":"ludovicus_dv","mother":"silvia_brissinck","spouses":[{"id":"octavia_schal","name":"Octavia Maria Schalandrijn","detail":"m. Oostende, 10 Nov 1906"}],"source":"gverdievel (Guy Verdievel); Marriage act nr. 258 — Eugenius Alphonsius Devriendt × Octavia Maria Schalandrijn, Oostende, 10 November 1906","note":"Born in Stene; father of Adrienne Devriendt.\n\nUPGRADED (2026-07-26): birth date and place (Stene, 13 April 1882) confirmed by his\nown 1906 Oostende marriage act (nr. 258, S20), read as an image — moved from sup\n(tree-gverdievel) to doc.\n\nGRAFTED (2026-07-26): parents identified from the same act — father Ludovicus\nJosephus Devriendt (already deceased by 1906), mother Silvia Rosalia Brissinck (alive,\npresent and consenting, werkvrouw, living at Steene). See [[ludovicus_dv]] and\n[[silvia_brissinck]] for what the act does and does not support about them beyond\nthis.\n\nFRONTIER — three children not yet entered as records (pass-2 material; vrijwilligersrab\nGeboorten index, not read at image level): Ludovicus Josephus (b. Stene 1907-02-07,\nact 7), August Bernard (b. Stene 1909-05-12, act 44), Germaine Marceline (b. Stene\n1920-07-03, act 50). A fourth child, Adrienne Margaretha (b. Stene 1908-04-12), already\nhas a record — see [[adrienne_dv]], which now carries her birth act reference (act 29)\nas corroboration."});
FamilyTree.person({"id":"felix_v","name":"Felix Guillielmus Vanstechelman","dates":"13 Feb 1800 Zevekote – 9 Nov 1869 Mariakerke","confidence":"sup","surname":"Vanstechelman","family":"vanstechelman","born":"13 Feb 1800 Zevekote","order":"1800-02-13","died":"9 Nov 1869 Mariakerke","occupation":"herbergier (innkeeper)","branch":"Vanstechelman","line":"vanstechelman","father":"pieterjacobus_v","mother":"carolina_vh","spouses":[{"id":"sophiavdb","name":"Sophia Van den Broucke","detail":"m. Mariakerke, 19 Dec 1844"}],"source":"stechec (Christian Vanstechelman)","note":"An innkeeper who moved the family from inland Zevekote to the coastal village of Mariakerke, near Oostende. Our line is via his 2nd wife, Sophia Van den Broucke."});
FamilyTree.person({"id":"florentinus_stroobandt","name":"Florentinus Stroobandt","dates":"1811 – 4 Mar 1876 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1811","order":"1811","died":"4 Mar 1876 Oostkamp","branch":"Bundervoet","line":"bostyn-cappaert","father":"jacobus_stroobandt","mother":"joanna_keirsebilck","spouses":[{"id":"rosalia_caeckaert","name":"Rosalia Caeckaert","detail":"m. Beernem, 29 Sep 1836"}],"source":"Death act of Florentinus Stroobandt, Oostkamp, 4 March 1876; kathrynann; Ancestry","note":"Father of Juliana Stroobandt (1839 Oedelem/Beernem). His own parents Jacobus Stroobandt × Joanna Keirsebilck are named in the same tree.\n\nDOCUMENTED DATE (July 2026). His death act gives **4 March 1876 at Oostkamp**, where the\ntree had only the year, and names [[rosalia_caeckaert]] as his wife."});
FamilyTree.person({"id":"francine_bisschop","name":"Francine Bisschop","dates":"","confidence":"sup","surname":"Bisschop","family":"bisschop","sex":"f","branch":"Bundervoet","line":"bundervoet","spouses":[{"id":"marcel_b","name":"Marcel Henri Bundervoet"}],"source":"Familiekunde Vlaanderen Westkust memorial card — Marcel Bundervoet, d. Oostende 20 November 2015","note":"Second partner of [[marcel_b]]. The Familiekunde Vlaanderen Westkust memorial-card\nindex names both his partners — her and a Van Iseghem ([[rosette]]) — which is what\nindependently confirmed the two marriages the family had reported.\n\n`sup`: the index is a transcription of the card, and nobody here has read the card\nitself. No dates, no marriage date, no children recorded. His three children\nare [[rosette]]'s."});
