FamilyTree.person({"id":"jacobus_stroobandt","name":"Jacobus Stroobandt","dates":"1 Sep 1782 Oostkamp – 24 Jun 1821 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1 Sep 1782 Oostkamp","order":"1782-09-01","died":"24 Jun 1821 Oostkamp","occupation":"schoenmaker (shoemaker)","branch":"Bundervoet","line":"bostyn-cappaert","father":"adrianus_stroobandt","mother":"anna_m_vanacker","spouses":[{"id":"isabella_demuynck","name":"Isabella De Muynck"},{"id":"joanna_keirsebilck","name":"Joanna Keirsebilck","detail":"m. Oostkamp, 24 Jul 1810"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Grandfather of Juliana Stroobandt, shoemaker. Married Isabella De Muynck (1782-1809), then Joanna Keirsebilck 24 Jul 1810. Parents Adrianus Stroobandt x Anna Maria Van Acker."});
