FamilyTree.person({"id":"maria_deruwe","name":"Maria De Ruwe","dates":"~1500 – ~1547","confidence":"sup","surname":"De Ruwe","family":"deruwe","born":"~1500","order":"1500","died":"~1547","branch":"Bundervoet","line":"bostyn-cappaert","spouses":[{"id":"mattheus_wittenheyns","name":"Mattheus Wittenheyns"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"DEEPEST CONFIRMED ANCESTOR (with her husband). Named in the 1547 Bruges orphan register. Later remarried Cornelis Immezeune. Born ~1500. No parents recorded. (Note: a different, later Maria De Ruwe exists in the same tree — not to be confused.)"});
