FamilyTree.person({"id":"maria_wolf","name":"Maria Wolf","dates":"","confidence":"sup","surname":"Wolf","family":"wolf","occupation":"herbergierster (innkeeper)","branch":"Thumas","line":"thumas","spouses":[{"id":"jbbossin","name":"Joannes Baptista Bossin"}],"source":"Marriage act nr. 3 — Ludovicus Bossin × Maria Isabella Helena Thumas, Kraainem, 10 April 1900","note":"Mother of the groom in her son [[ludovicus_bossin79]]'s marriage act — Kraainem nr. 3, 10\nApril 1900 (S28). A *herbergierster* of Sint-Stevens-Woluwe: she kept an inn, as her son's\nnew father-in-law [[georges_cj]] did at Kraainem.\n\nWidowed since 1887 and running the house herself thirteen years later — the act gives her the\ntrade in her own right, not her husband's.\n\nNo dates: the act gives none. *Wolf* is rare enough in this corner of Brabant to be searchable\non its own, which is the cheap next move."});
FamilyTree.person({"id":"marie_anna_dedeckere","name":"Marie Anna de Deckere","dates":"~1731 – 1809","confidence":"sup","surname":"de Deckere","family":"dedeckere","sex":"f","born":"~1731","order":"1731","died":"1809","branch":"Bundervoet","line":"bundervoet","spouses":[{"id":"petrus_b1727","name":"Petrus (Pieter) Bundervoet","detail":"m. ~1750"}],"source":"paulderidder","note":"Wife of [[petrus_b1727]] and mother of his eight children, so a great-aunt by marriage of\nthis tree's direct line rather than an ancestor of it.\n\nShe outlived him by more than thirty years: he was buried at Assenede in 1777, she died in\n1809. Her own parents are not recorded in the paulderidder tree, and nothing else has been\nread for her."});
FamilyTree.person({"id":"marie_vanbergen","name":"Marie-Louise Van Bergen","dates":"1842 – 1888","confidence":"doc","surname":"Van Bergen","family":"vanbergen","born":"1842","order":"1842","died":"1888","branch":"DeKeyser","line":"de-keyser","father":"jan_van_bergen","mother":"ida_vermandel","spouses":[{"id":"edouard_bocklandt","name":"Édouard Bocklandt"}],"source":"wete1998 (Erik Bekaert) — Hamme (O-Vl) specialist; Rijksarchief AGATHA — Belgian State Archives search robot","note":"Mother of Louise Marie Bocklandt (1877, Hamme O-Vl). Full name Maria Louisa Van Bergen, 1842-1888. Her parents were Joannes Franciscus Van Bergen (1815-1898) × Ida Vermandel (1825-1865), of Hamme (Oost-Vlaanderen)."});
