FamilyTree.person({"id":"mathilde_desmet","name":"Mathilde Desmet","dates":"b. 21 Feb 1841 Sint-Andries","confidence":"sup","surname":"Desmet","family":"desmet","born":"21 Feb 1841 Sint-Andries","order":"1841-02-21","branch":"Bundervoet","line":"bostyn-cappaert","spouses":[{"id":"henricus_j_bostyn","name":"Henricus Josephus Bostyn","detail":"m. Sint-Andries, 11 Sep 1867"}],"note":"Married 1867 Sint-Andries. Born 21 Feb 1841 Sint-Andries. Her parents are the frontier (her 1841 Sint-Andries birth act)."});
FamilyTree.person({"id":"mathilde_standaert","name":"Mathilde Standaert","dates":"","confidence":"doc","surname":"Standaert","family":"standaert","occupation":"huishoudster (housekeeper)","branch":"Bundervoet","line":"van-iseghem","spouses":[{"id":"ludovicus_schal","name":"Ludovicus Franciscus Schalandryn"}],"source":"Marriage act nr. 258 — Eugenius Alphonsius Devriendt × Octavia Maria Schalandrijn, Oostende, 10 November 1906; Birth act nr. 116 — Octavia Maria Schalandrijn, Bredene, certificate dated 2 May 1886; West-Vlaamse Burgerlijke Stand — Huwelijken (marriage index), Rijksarchief Brugge/Kortrijk volunteers; West-Vlaamse Burgerlijke Stand — Geboorten (birth index), Rijksarchief Brugge/Kortrijk volunteers","note":"Named as mother of the bride in her daughter Octavia's 1906 Oostende marriage act (nr.\n258, S20), read as an image — \"overleden\" (deceased) by that date, no date given there.\nThe Bredene birth act (nr. 116, 1886, S21), also read as an image, names her as the\ndeclarant's wife, age 42, occupation \"huishoudster\", \"geboortig van Brugge\" (native of\nBruges) — a birthplace stated directly by the act, though the act gives no birth date\nfor her, only her age.\n\nFRONTIER — her age of 42 in the 1886 act implies a birth around 1844, but that is a\nderivation from an age, not a birth date, and is not recorded as one. The\nvrijwilligersrab Geboorten index carries an unread entry giving Brugge, 17 March 1844 —\nconsistent with the derived year, but not read at image level, so not graftable. Her\nown parents, also index-only and unread: Petrus Standaert x Anna Deckers.\n\nEach needs the underlying act image read before it becomes a fact (verification pass,\n2026-07-26)."});
FamilyTree.person({"id":"mattheus_ramon","name":"Mattheus Ramon","dates":"4 Aug 1729 Bovekerke – 31 Oct 1790 Handzame","confidence":"sup","surname":"Ramon","family":"ramon","born":"4 Aug 1729 Bovekerke","order":"1729-08-04","died":"31 Oct 1790 Handzame","branch":"Devriendt","line":"devriendt","father":"stephanus_ramon","mother":"joanna_truant","spouses":[{"id":"anna_norysse","name":"Anna Anastasia Norysse"},{"id":"jacoba_ossaert","name":"Jacoba Josepha Ossaert","detail":"m. Zande, 31 May 1772"}],"source":"wernero (Werner Osaer)","note":"Son of Stephanus Ramon & Joanna Truant; married twice — our line is via his 2nd wife Jacoba Ossaert (Zande, 1772), with whom he had ten children."});
FamilyTree.person({"id":"mattheus_wittenheyns","name":"Mattheus Wittenheyns","dates":"~1500 – ~1546 Oostkamp","confidence":"sup","surname":"Wittenheyns","family":"wittenheyns","born":"~1500","order":"1500","died":"~1546 Oostkamp","branch":"Bundervoet","line":"bostyn-cappaert","spouses":[{"id":"maria_deruwe","name":"Maria De Ruwe"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"DEEPEST CONFIRMED ANCESTOR (with his wife). Called 'gheseyt Maraels'. Named with wife and children in the 1547 Bruges orphan register (weesregister St.-Jan). Born ~1500 — the reign of Charles V. No parents recorded."});
