FamilyTree.person({"id":"michael_devriese_o","name":"Michaël De Vriese","dates":"1615 – 1681","confidence":"sup","surname":"De Vriese","family":"devriese","born":"1615","order":"1615","died":"1681","branch":"Bundervoet","line":"bostyn-cappaert","spouses":[{"id":"judoca_scherrens","name":"Judoca Scherrens"}],"source":"isavdw — Rijksarchief-sourced, with scan links; kathrynann","note":"FRONTIER above — born ~1615, one of the deepest documented ancestors in the tree. Parents not verified (a 1674 namesake Michaël De Vriese exists in the same source — not to be confused)."});
