FamilyTree.person({"id":"pierre_ramon","name":"Pierre Francois Ramon","dates":"23 Feb 1812 Mariakerke – 1 Oct 1858 Oostende","confidence":"sup","surname":"Ramon","family":"ramon","born":"23 Feb 1812 Mariakerke","order":"1812-02-23","died":"1 Oct 1858 Oostende","occupation":"tuinier & zeeman (gardener/seaman)","branch":"Devriendt","line":"devriendt","father":"henricus_j_ramon","mother":"lucia_steenkiste","spouses":[{"id":"joanna_daneel","name":"Joanna Theresia Daneel","detail":"m. Oostende, 28 Jan 1835"}],"source":"wernero (Werner Osaer)","note":"A gardener and seaman who DROWNED AT SEA in October 1858. First wife Joanna Daneel (our line); he had remarried Anna Degroo in 1857."});
