FamilyTree.person({"id":"wilhelmina_b1650","name":"Wilhelmina Bundervoet","dates":"b. ~1650","confidence":"sup","surname":"Bundervoet","family":"bundervoet","sex":"f","born":"~1650","order":"1650","branch":"Bundervoet","line":"bundervoet","father":"livinus_bundervoet","mother":"catharina_vanhecke","source":"paulderidder","note":"Daughter of [[livinus_bundervoet]] by his second wife [[catharina_vanhecke]], and so a\nhalf-sister of [[segerius_bundervoet]] — a blood relative of Renée and Léon through their\nshared father.\n\nThe paulderidder tree lists her under Segerius's half-siblings with a birth of about 1650 and\nnothing else. No act read."});
FamilyTree.person({"id":"willem_sabbe_o","name":"Willem Sabbe","dates":"~1530 Harelbeke (Bavikhove) – 1581 Wielsbeke (Ooigem)","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1530 Harelbeke (Bavikhove)","order":"1530","died":"1581 Wielsbeke (Ooigem)","occupation":"landbouwer (farmer)","branch":"Bundervoet","line":"bostyn-cappaert","father":"petrus_sabbe_1504","spouses":[{"id":"magdalena_demeulemeester","name":"Magdalena Demeulemeester","detail":"m. ~1555"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Source detail: Geneanet isavdw (Sosa 27040)\n\nGrandfather of Petrus Sabbe (d.1652); farmer around Harelbeke/Wielsbeke (the Sabbe family's cradle, before the line moved to Oostkamp). Father Petrus Sabbe (1504-1557)."});
FamilyTree.person({"id":"willem_sabbe_y","name":"Willem Sabbe","dates":"b. 1560–1569","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"1560–1569","order":"1560","branch":"Bundervoet","line":"bostyn-cappaert","father":"willem_sabbe_o","mother":"magdalena_demeulemeester","spouses":[{"id":"clara_vandeputte","name":"Clara Vande Putte"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Father of Petrus Sabbe (d.1652). Son of Willem Sabbe (~1530-1581); brother of Michiel Sabbe (b.1557), who witnessed Petrus's 1616 marriage."});
FamilyTree.person({"id":"willem_vanhecke","name":"Willem van Hecke","dates":"b. ~1580","confidence":"sup","surname":"van Hecke","family":"vanhecke","born":"~1580","order":"1580","branch":"Bundervoet","line":"bundervoet","spouses":[{"name":"(wife unrecorded)"}],"source":"paulderidder","note":"Father of Joanna (Janneken) van Hecke (~1610–1678), who married Segerius Bundervoet —\nso a direct ancestor, and with a birth about 1580 one of the earliest people in the\ntree.\n\nThe paulderidder chart gives him as her father, born about 1580, with the mother shown\nonly as \"?\". Joanna's record previously said her parents were \"not recorded here\";\nthey were.\n\nWORTH NOTING, NOT YET CLAIMED: Livinus Bundervoet's second wife was a Catharina van\nHecke (~1620–~1670), while his son Segerius married this Joanna van Hecke (~1610).\nTwo van Hecke women marrying father and son suggests one van Hecke family, and\npossibly sisters — but nothing seen so far states a relationship between them, so\nnone is recorded here."});
FamilyTree.person({"id":"yvonne","name":"Yvonne Smessaert","dates":"b. 11 Oct 1914 Oostende","confidence":"sup","surname":"Smessaert","family":"smessaert","born":"11 Oct 1914 Oostende","order":"1914-10-11","branch":"Devriendt","line":"devriendt","father":"georgius_s","mother":"devos","spouses":[{"id":"marcel_d","name":"Marcel Devriendt","detail":"m. Stene, 16 Oct 1937"}],"source":"wernero (Werner Osaer)","note":"Born before her parents wed and legitimized by their 1919 marriage; married Marcel Devriendt in 1937. Born 11 October — the same day-and-month as her father's birthday."});
